package dev.folio.app.spikes

import android.annotation.SuppressLint
import android.app.Activity
import android.graphics.Bitmap
import android.graphics.Canvas
import android.graphics.Paint
import android.graphics.Rect
import android.os.SystemClock
import android.view.Choreographer
import android.view.MotionEvent
import android.view.PixelCopy
import android.view.View
import androidx.annotation.MainThread
import androidx.annotation.WorkerThread
import dev.folio.core.common.FolioDispatchers
import dev.folio.core.common.PerfMonitor
import dev.folio.core.render.DisplayModeHelper
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.cancel
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.buildJsonObject
import kotlinx.serialization.json.put
import kotlin.math.min
import kotlin.math.roundToInt

/**
 * Spike P01-S2: an A4 lined page with 1500 seeded strokes shown through 512 px tiles, either
 * software bitmaps (A) or RenderNodes with compositing layers (B). Finger drag pans; zoom is
 * scripted (`debugcmd.sh zoom-anim`). During gestures tiles are only transformed; 100 ms after
 * the gesture the current zoom bucket renders center-out (05-canvas-rendering.md#tiles).
 * Deleted or promoted by P01-T08.
 */
@SuppressLint("ViewConstructor") // created in code by AppDebugHooks only
@Suppress("TooManyFunctions") // spike screen: viewport, input, scripted zoom and verify in one place until P01-T08
@MainThread
internal class SpikeTilesView(
    private val activity: Activity,
    private val dispatchers: FolioDispatchers,
) : View(activity) {
    private val scope = CoroutineScope(SupervisorJob() + dispatchers.main)
    private val cache = SpikeTileCache(dispatchers, scope, ::onTileReady)
    private val displayModes = DisplayModeHelper(activity.window)
    private val pagePaint = Paint().apply { color = PAPER_ARGB }
    private val idle = Runnable { onGestureIdle() }
    private val zoomFrame = Choreographer.FrameCallback(::onZoomFrame)
    private val sidePaddingPx = SIDE_PADDING_DP * resources.displayMetrics.density
    private val topPaddingPx = TOP_PADDING_DP * resources.displayMetrics.density
    private var lastX = 0f
    private var lastY = 0f
    private var lastRequestMs = 0L
    private var settleStartNs = 0L
    private var verifyPending = false
    private var animFrom = 1f
    private var animTo = 1f
    private var animStartNs = 0L
    private var animDurationNs = 0L

    /** Zoom as a multiple of fit-width. */
    var zoom = 1f
        private set

    /** Current px per pt; 0 until laid out. */
    var scale = 0f
        private set
    var offsetXPx = 0f
        private set
    var offsetYPx = 0f
        private set

    /** Zoom bucket tiles are rendered at; follows [scale] 100 ms after a gesture. */
    var bucket = 0
        private set
    var seedMs: Double? = null
        private set
    var strokeCount = 0
        private set
    var requestedHz: Float? = null
        private set
    var lastVerify: JsonObject? = null
        private set
    val strategy: TileStrategy get() = cache.strategy
    val tileCount: Int get() = cache.tileCount
    val pendingCount: Int get() = cache.pendingCount
    val pooledCount: Int get() = cache.pooledCount

    override fun onAttachedToWindow() {
        super.onAttachedToWindow()
        requestedHz = display?.let(displayModes::request)
        scope.launch {
            val startNs = SystemClock.elapsedRealtimeNanos()
            val page =
                withContext(dispatchers.render) {
                    PerfMonitor.trace(SECTION_SEED) {
                        SpikePage.create(SyntheticStrokes.generate(SpikePage.WIDTH_PT, SpikePage.HEIGHT_PT))
                    }
                }
            seedMs = (SystemClock.elapsedRealtimeNanos() - startNs) / NS_PER_MS
            strokeCount = page.strokeCount
            cache.renderer = SpikeTileRenderer(page)
            settleStartNs = SystemClock.elapsedRealtimeNanos()
            requestVisible()
        }
    }

    override fun onDetachedFromWindow() {
        Choreographer.getInstance().removeFrameCallback(zoomFrame)
        removeCallbacks(idle)
        scope.cancel()
        cache.reset()
        displayModes.release()
        super.onDetachedFromWindow()
    }

    override fun onSizeChanged(
        w: Int,
        h: Int,
        oldw: Int,
        oldh: Int,
    ) {
        if (scale == 0f) {
            scale = fitScale() * zoom
            offsetYPx = topPaddingPx
            clamp()
            bucket = TileMath.bucketIndex(scale)
        }
        requestVisible()
    }

    /** Drops all tiles and renders the visible ones again with [next]. */
    fun switchStrategy(next: TileStrategy) {
        cache.reset(next)
        settleStartNs = SystemClock.elapsedRealtimeNanos()
        requestVisible()
        invalidate()
    }

    /** Jumps to [target] zoom around the view center and re-renders at once. */
    fun jumpToZoom(target: Float) {
        Choreographer.getInstance().removeFrameCallback(zoomFrame)
        applyZoom(target)
        onGestureIdle()
    }

    /** Animates zoom [from] -> [to] around the view center over [durationMs] (smoothstep), one step per frame. */
    fun animateZoom(
        from: Float,
        to: Float,
        durationMs: Long,
    ) {
        removeCallbacks(idle)
        applyZoom(from)
        animFrom = from
        animTo = to
        animStartNs = 0L
        animDurationNs = durationMs * NS_PER_MS.toLong()
        Choreographer.getInstance().removeFrameCallback(zoomFrame)
        Choreographer.getInstance().postFrameCallback(zoomFrame)
    }

    /**
     * Snaps the scale to its bucket (1:1 tile pixels) and integer offsets, waits for the visible
     * tiles, then compares the window pixels with a direct render of the page ([lastVerify]).
     */
    fun verify() {
        applyZoom(TileMath.bucketScale(TileMath.bucketIndex(scale)) / fitScale())
        offsetXPx = offsetXPx.roundToInt().toFloat()
        offsetYPx = offsetYPx.roundToInt().toFloat()
        verifyPending = true
        lastVerify = buildJsonObject { put("state", "pending") }
        onGestureIdle()
        invalidate()
    }

    override fun onDraw(canvas: Canvas) =
        PerfMonitor.trace(SECTION_DRAW) {
            // HOT PATH: every frame during pan and zoom; no allocation.
            canvas.drawColor(SURROUND_ARGB)
            if (scale == 0f) return@trace
            val right = offsetXPx + SpikePage.WIDTH_PT * scale
            val bottom = offsetYPx + SpikePage.HEIGHT_PT * scale
            canvas.drawRect(offsetXPx, offsetYPx, right, bottom, pagePaint)
            cache.draw(canvas, bucket, scale, offsetXPx, offsetYPx)
        }

    @SuppressLint("ClickableViewAccessibility") // spike: one-finger pan only, no click action
    override fun onTouchEvent(event: MotionEvent): Boolean {
        // HOT PATH: per MotionEvent; no allocation.
        when (event.actionMasked) {
            MotionEvent.ACTION_DOWN -> {
                lastX = event.x
                lastY = event.y
                removeCallbacks(idle)
            }

            MotionEvent.ACTION_MOVE -> {
                offsetXPx += event.x - lastX
                offsetYPx += event.y - lastY
                lastX = event.x
                lastY = event.y
                clamp()
                invalidate()
                val nowMs = SystemClock.uptimeMillis()
                if (nowMs - lastRequestMs >= PAN_REQUEST_INTERVAL_MS) {
                    lastRequestMs = nowMs
                    requestVisible() // same bucket while panning: render newly exposed tiles right away
                }
            }

            MotionEvent.ACTION_UP, MotionEvent.ACTION_CANCEL -> {
                postDelayed(idle, IDLE_MS)
            }
        }
        return true
    }

    private fun onZoomFrame(frameTimeNanos: Long) {
        if (animStartNs == 0L) animStartNs = frameTimeNanos
        val t = min(1f, (frameTimeNanos - animStartNs).toFloat() / animDurationNs)
        val eased = t * t * (3f - 2f * t)
        applyZoom(animFrom + (animTo - animFrom) * eased)
        if (t < 1f) Choreographer.getInstance().postFrameCallback(zoomFrame) else postDelayed(idle, IDLE_MS)
    }

    private fun fitScale(): Float = (width - 2 * sidePaddingPx) / SpikePage.WIDTH_PT

    /** Sets [target] zoom keeping the page point under the view center fixed (focal-point zoom). */
    private fun applyZoom(target: Float) {
        if (width == 0) return
        val next = fitScale() * target.coerceIn(MIN_ZOOM, MAX_ZOOM)
        val focusX = width / 2f
        val focusY = height / 2f
        val pageX = (focusX - offsetXPx) / scale
        val pageY = (focusY - offsetYPx) / scale
        zoom = target.coerceIn(MIN_ZOOM, MAX_ZOOM)
        scale = next
        offsetXPx = focusX - pageX * next
        offsetYPx = focusY - pageY * next
        clamp()
        invalidate()
    }

    /** Centers a page narrower than the view; otherwise allows half a screen of overscroll. */
    private fun clamp() {
        val contentW = SpikePage.WIDTH_PT * scale
        val contentH = SpikePage.HEIGHT_PT * scale
        offsetXPx =
            if (contentW <= width) (width - contentW) / 2f else offsetXPx.coerceIn(width / 2f - contentW, width / 2f)
        offsetYPx = offsetYPx.coerceIn(height / 2f - contentH, height / 2f)
    }

    private fun onGestureIdle() {
        val next = TileMath.bucketIndex(scale)
        if (next != bucket) {
            bucket = next
            settleStartNs = SystemClock.elapsedRealtimeNanos()
        }
        requestVisible()
        onTileReady()
    }

    private fun visibleRange(ring: Int): TileRange =
        TileMath.visibleTiles(
            SpikePage.WIDTH_PT,
            SpikePage.HEIGHT_PT,
            scale,
            offsetXPx,
            offsetYPx,
            width,
            height,
            TileMath.bucketScale(bucket),
            ring,
        )

    private fun requestVisible() {
        if (width == 0 || scale == 0f) return
        val toBucket = TileMath.bucketScale(bucket) / scale
        val order = TileMath.centerOut(visibleRange(ring = 1), (width / 2f - offsetXPx) * toBucket, (height / 2f - offsetYPx) * toBucket)
        cache.request(bucket, order)
    }

    /** After a tile arrives: record settle time, evict replaced tiles, run a pending verify. */
    private fun onTileReady() {
        invalidate()
        if (scale == 0f || !cache.complete(bucket, visibleRange(ring = 0))) return
        if (settleStartNs != 0L) {
            PerfMonitor.record("tiles:settle${strategy.name}", SystemClock.elapsedRealtimeNanos() - settleStartNs)
            settleStartNs = 0L
        }
        cache.evict(bucket, visibleRange(ring = 2))
        if (verifyPending) {
            verifyPending = false
            viewTreeObserver.registerFrameCommitCallback(::capture) // after the frame showing every tile
        }
    }

    private fun capture() {
        val renderer = cache.renderer ?: return
        val location = IntArray(2).also(::getLocationInWindow)
        val shot = Bitmap.createBitmap(width, height, Bitmap.Config.ARGB_8888)
        val source = Rect(location[0], location[1], location[0] + width, location[1] + height)
        val snapshot = ViewSnapshot(strategy, scale, offsetXPx, offsetYPx)
        PixelCopy.request(activity.window, source, shot, { result ->
            if (result != PixelCopy.SUCCESS) {
                lastVerify = buildJsonObject { put("error", "PixelCopy result $result") }
                return@request
            }
            scope.launch { lastVerify = withContext(dispatchers.render) { compare(shot, renderer, snapshot) } }
        }, handler)
    }

    @WorkerThread
    private fun compare(
        shot: Bitmap,
        renderer: SpikeTileRenderer,
        at: ViewSnapshot,
    ): JsonObject {
        val reference = Bitmap.createBitmap(shot.width, shot.height, Bitmap.Config.ARGB_8888)
        val canvas = Canvas(reference)
        canvas.drawColor(SURROUND_ARGB)
        val paper = Paint().apply { color = PAPER_ARGB }
        canvas.drawRect(
            at.offsetXPx,
            at.offsetYPx,
            at.offsetXPx + SpikePage.WIDTH_PT * at.scale,
            at.offsetYPx + SpikePage.HEIGHT_PT * at.scale,
            paper,
        )
        renderer.renderReference(canvas, at.scale, at.offsetXPx, at.offsetYPx)
        val diff = PixelDiff().addBitmaps(shot, reference)
        reference.recycle()
        shot.recycle()
        return buildJsonObject {
            put("strategy", at.strategy.name)
            put("scale", at.scale)
            put("pixels", diff.pixels)
            put("differingPct", diff.differingPct)
            put("meanChannelDiff", diff.meanChannelDiff)
        }
    }

    private class ViewSnapshot(
        val strategy: TileStrategy,
        val scale: Float,
        val offsetXPx: Float,
        val offsetYPx: Float,
    )

    companion object {
        const val ROUTE = "spike-tiles"
        const val SECTION_SEED = "tiles:seed"
        const val SECTION_DRAW = "tiles:draw"
        const val MIN_ZOOM = 0.25f
        const val MAX_ZOOM = 8f
        private const val IDLE_MS = 100L
        private const val PAN_REQUEST_INTERVAL_MS = 50L
        private const val SIDE_PADDING_DP = 24f
        private const val TOP_PADDING_DP = 16f
        private const val NS_PER_MS = 1_000_000.0
        private const val SURROUND_ARGB = 0xFFE9ECF1.toInt()
        private const val PAPER_ARGB = 0xFFFFFFFF.toInt()
    }
}

package dev.folio.app.spikes

import dev.folio.app.debug.DebugReply
import kotlinx.serialization.json.buildJsonObject
import kotlinx.serialization.json.put

/** Parsed `zoom-anim from,to,durationMs` argument. */
internal data class ZoomAnim(
    val from: Float,
    val to: Float,
    val durationMs: Long,
) {
    companion object {
        private const val PARTS = 3
        private const val MAX_DURATION_MS = 10_000L

        /** Null unless [arg] is three comma-separated numbers with zooms in range and 1..10000 ms. */
        fun parse(arg: String?): ZoomAnim? {
            val parts = arg?.split(',')?.takeIf { it.size == PARTS } ?: return null
            val zoomRange = SpikeTilesView.MIN_ZOOM..SpikeTilesView.MAX_ZOOM
            val from = parts[0].toFloatOrNull()?.takeIf { it in zoomRange }
            val to = parts[1].toFloatOrNull()?.takeIf { it in zoomRange }
            val durationMs = parts[2].toLongOrNull()?.takeIf { it in 1..MAX_DURATION_MS }
            return if (from != null && to != null && durationMs != null) ZoomAnim(from, to, durationMs) else null
        }
    }
}

/**
 * `debugcmd.sh spike-tiles [stats|a|b|zoom=<z>|verify]` for P01-S2: reports viewport and cache
 * counters (and the last verify result), switches the tile strategy, jumps to a zoom, or starts a
 * pixel comparison against a direct render. [view] is null while the route is hidden.
 */
internal fun spikeTilesCommand(
    view: SpikeTilesView?,
    arg: String?,
): DebugReply {
    if (view == null) return DebugReply.error("route ${SpikeTilesView.ROUTE} is not shown")
    val zoom = arg?.removePrefix("zoom=")?.takeIf { arg.startsWith("zoom=") }
    when {
        arg == null || arg == "stats" -> Unit
        arg == "verify" -> view.verify()
        zoom != null -> view.jumpToZoom(zoom.toFloatOrNull() ?: return DebugReply.error("zoom needs a number"))
        else -> view.switchStrategy(TileStrategy.parse(arg) ?: return DebugReply.error("spike-tiles needs stats|a|b|zoom=<z>|verify"))
    }
    return DebugReply.ok(
        buildJsonObject {
            put("strategy", view.strategy.name)
            put("strokes", view.strokeCount)
            put("seedMs", view.seedMs)
            put("zoom", view.zoom)
            put("scale", view.scale)
            put("bucket", view.bucket)
            put("tiles", view.tileCount)
            put("pending", view.pendingCount)
            put("pooled", view.pooledCount)
            put("requestedHz", view.requestedHz)
            put("activeHz", view.display?.refreshRate)
            view.lastVerify?.let { put("verify", it) }
        },
    )
}

/** `debugcmd.sh zoom-anim from,to,durationMs`: animates zoom on the tile spike screen (P01-S2). */
internal fun zoomAnimCommand(
    view: SpikeTilesView?,
    arg: String?,
): DebugReply {
    if (view == null) return DebugReply.error("route ${SpikeTilesView.ROUTE} is not shown")
    val anim = ZoomAnim.parse(arg) ?: return DebugReply.error("zoom-anim needs from,to,durationMs (zoom 0.25..8, 1..10000 ms)")
    view.animateZoom(anim.from, anim.to, anim.durationMs)
    return DebugReply.ok(
        buildJsonObject {
            put("from", anim.from)
            put("to", anim.to)
            put("durationMs", anim.durationMs)
        },
    )
}

package dev.folio.app.spikes

import android.graphics.Bitmap
import android.graphics.Canvas
import android.graphics.Paint
import androidx.annotation.MainThread
import dev.folio.core.common.FolioDispatchers
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Job
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext

/**
 * Tile cache of the P01-S2 spike: renders missing tiles on the render dispatcher (center-out),
 * keeps other-bucket tiles on screen until the current bucket is complete, pools bitmaps (A).
 * Main thread only; [onTileReady] fires after each accepted tile.
 */
@MainThread
internal class SpikeTileCache(
    private val dispatchers: FolioDispatchers,
    private val scope: CoroutineScope,
    private val onTileReady: () -> Unit,
) {
    private val tiles = ArrayList<SpikeTile>()
    private val inFlight = HashMap<Long, Job>()
    private val pool = ArrayDeque<Bitmap>()
    private val bitmapPaint = Paint(Paint.FILTER_BITMAP_FLAG)
    private var generation = 0

    var renderer: SpikeTileRenderer? = null
    var strategy = TileStrategy.A
        private set

    val tileCount: Int get() = tiles.size
    val pendingCount: Int get() = inFlight.size
    val pooledCount: Int get() = pool.size

    /** Drops every tile and in-flight render, then switches to [next]. */
    fun reset(next: TileStrategy = strategy) {
        generation++
        inFlight.values.forEach { it.cancel() }
        inFlight.clear()
        tiles.forEach(::recycle)
        tiles.clear()
        strategy = next
    }

    /** Starts renders for the [order]ed tiles of [bucket] that are neither cached nor in flight. */
    fun request(
        bucket: Int,
        order: List<Pair<Int, Int>>,
    ) {
        val renderer = renderer ?: return
        val stale = inFlight.entries.iterator()
        while (stale.hasNext()) {
            val (key, job) = stale.next()
            if (tileBucket(key) == bucket) continue
            job.cancel() // an old bucket nobody waits for; its bitmap returns to the pool
            stale.remove()
        }
        val section = "tiles:render${strategy.name}:b$bucket"
        for ((tx, ty) in order) {
            val key = tileKey(bucket, tx, ty)
            if (key in inFlight || tiles.any { it.key == key }) continue
            inFlight[key] = launch(renderer, bucket, tx, ty, section)
        }
    }

    /** True when every tile of [range] at [bucket] is cached. */
    fun complete(
        bucket: Int,
        range: TileRange,
    ): Boolean {
        if (range.isEmpty) return true
        var have = 0
        for (tile in tiles) if (tile.bucket == bucket && range.contains(tile.tx, tile.ty)) have++
        return have == (range.txMax - range.txMin + 1) * (range.tyMax - range.tyMin + 1)
    }

    /** Drops tiles of other buckets and current-bucket tiles outside [keep]. */
    fun evict(
        bucket: Int,
        keep: TileRange,
    ) {
        tiles.removeAll { tile -> (tile.bucket != bucket || !keep.contains(tile.tx, tile.ty)).also { if (it) recycle(tile) } }
    }

    /** Draws cached tiles for a view at [scale] with the page origin at ([offsetXPx], [offsetYPx]); current bucket on top. */
    fun draw(
        canvas: Canvas,
        bucket: Int,
        scale: Float,
        offsetXPx: Float,
        offsetYPx: Float,
    ) {
        // HOT PATH: runs every frame during pan and zoom; no allocation.
        for (pass in 0..1) {
            for (i in tiles.indices) {
                val tile = tiles[i]
                if ((tile.bucket == bucket) == (pass == 0)) continue
                drawTile(canvas, tile, scale, offsetXPx, offsetYPx)
            }
        }
    }

    private fun drawTile(
        canvas: Canvas,
        tile: SpikeTile,
        scale: Float,
        offsetXPx: Float,
        offsetYPx: Float,
    ) {
        val k = scale / tile.bucketScale
        val sizePx = TileMath.TILE_PX * k
        val left = offsetXPx + tile.tx * sizePx
        val top = offsetYPx + tile.ty * sizePx
        if (left > canvas.width || top > canvas.height || left + sizePx < 0f || top + sizePx < 0f) return
        canvas.save()
        canvas.translate(left, top)
        canvas.scale(k, k)
        tile.bitmap?.let { canvas.drawBitmap(it, 0f, 0f, bitmapPaint) }
        tile.node?.let { if (canvas.isHardwareAccelerated) canvas.drawRenderNode(it) }
        canvas.restore()
    }

    private fun launch(
        renderer: SpikeTileRenderer,
        bucket: Int,
        tx: Int,
        ty: Int,
        section: String,
    ): Job {
        val gen = generation
        val mode = strategy
        val bitmap = if (mode == TileStrategy.A) pool.removeLastOrNull() ?: newBitmap() else null
        return scope.launch {
            val tile =
                try {
                    withContext(dispatchers.render) { renderer.render(mode, bucket, tx, ty, bitmap, section) }
                } catch (e: CancellationException) {
                    bitmap?.let(::release) // withContext returns only after the render finished
                    throw e
                }
            if (gen != generation) {
                recycle(tile)
                return@launch
            }
            inFlight.remove(tile.key)
            tiles += tile
            onTileReady()
        }
    }

    private fun newBitmap(): Bitmap = Bitmap.createBitmap(TileMath.TILE_PX, TileMath.TILE_PX, Bitmap.Config.ARGB_8888)

    private fun recycle(tile: SpikeTile) {
        tile.bitmap?.let(::release)
        tile.node?.discardDisplayList()
    }

    private fun release(bitmap: Bitmap) {
        if (pool.size < POOL_MAX) pool.addLast(bitmap) else bitmap.recycle()
    }

    private companion object {
        const val POOL_MAX = 24
    }
}

package dev.folio.app.spikes

import android.graphics.Bitmap
import android.graphics.Canvas
import android.graphics.RenderNode
import androidx.annotation.WorkerThread
import dev.folio.core.common.PerfMonitor

/** Committed-content strategies compared by P01-S2 (decisions.md#adr-003-committed-content-rendering). */
internal enum class TileStrategy {
    /** Software ARGB_8888 bitmap per tile. */
    A,

    /** RenderNode per tile with a compositing layer (GPU-cached display list). */
    B,
    ;

    companion object {
        fun parse(name: String): TileStrategy? = entries.firstOrNull { it.name.equals(name, ignoreCase = true) }
    }
}

/** One rendered 512 px tile; exactly one of [bitmap] (A) and [node] (B) is set. */
internal class SpikeTile(
    val bucket: Int,
    val tx: Int,
    val ty: Int,
    val bitmap: Bitmap?,
    val node: RenderNode?,
) {
    val bucketScale: Float = TileMath.bucketScale(bucket)
    val key: Long get() = tileKey(bucket, tx, ty)
}

/** Packs a tile address into one Long; bucket and indices must lie in 0 until 2^21. */
internal fun tileKey(
    bucket: Int,
    tx: Int,
    ty: Int,
): Long = ((bucket.toLong() and MASK) shl SHIFT_BUCKET) or ((tx.toLong() and MASK) shl SHIFT_TX) or (ty.toLong() and MASK)

/** Bucket of a key made by [tileKey]. */
internal fun tileBucket(key: Long): Int = ((key ushr SHIFT_BUCKET) and MASK).toInt()

private const val MASK = 0x1FFFFFL
private const val SHIFT_BUCKET = 42
private const val SHIFT_TX = 21

/** Renders tiles of a [SpikePage] with either strategy; safe to call from several render threads. */
internal class SpikeTileRenderer(
    private val page: SpikePage,
) {
    private val painters = ThreadLocal.withInitial { SpikePage.Painter() }

    /** Renders tile ([tx], [ty]) at [bucket] into [bitmap] (A, reused from the pool) or a new RenderNode (B). */
    @WorkerThread
    fun render(
        strategy: TileStrategy,
        bucket: Int,
        tx: Int,
        ty: Int,
        bitmap: Bitmap?,
        section: String,
    ): SpikeTile =
        PerfMonitor.trace(section) {
            val scale = TileMath.bucketScale(bucket)
            val painter = painters.get() ?: SpikePage.Painter()
            val px = TileMath.TILE_PX.toFloat()
            val toDevice =
                painter.matrix.apply {
                    setScale(scale, scale)
                    postTranslate(-tx * px, -ty * px)
                }
            val leftPt = tx * px / scale
            val topPt = ty * px / scale
            val sizePt = px / scale
            when (strategy) {
                TileStrategy.A -> {
                    val target = checkNotNull(bitmap) { "strategy A needs a pooled bitmap" }
                    target.eraseColor(0)
                    val canvas = Canvas(target)
                    canvas.concat(toDevice)
                    page.draw(canvas, painter, leftPt, topPt, leftPt + sizePt, topPt + sizePt, toDevice)
                    SpikeTile(bucket, tx, ty, target, null)
                }

                TileStrategy.B -> {
                    val node = RenderNode("tile")
                    node.setPosition(0, 0, TileMath.TILE_PX, TileMath.TILE_PX)
                    node.setUseCompositingLayer(true, null)
                    val canvas = node.beginRecording(TileMath.TILE_PX, TileMath.TILE_PX)
                    try {
                        canvas.concat(toDevice)
                        page.draw(canvas, painter, leftPt, topPt, leftPt + sizePt, topPt + sizePt, toDevice)
                    } finally {
                        node.endRecording()
                    }
                    SpikeTile(bucket, tx, ty, null, node)
                }
            }
        }

    /** Draws the page directly (no tiles) as seen by a view at [scale] and offset: the verify reference. */
    @WorkerThread
    fun renderReference(
        canvas: Canvas,
        scale: Float,
        offsetXPx: Float,
        offsetYPx: Float,
    ) {
        val painter = painters.get() ?: SpikePage.Painter()
        val toDevice =
            painter.matrix.apply {
                setScale(scale, scale)
                postTranslate(offsetXPx, offsetYPx)
            }
        canvas.save()
        canvas.concat(toDevice)
        page.draw(
            canvas,
            painter,
            -offsetXPx / scale,
            -offsetYPx / scale,
            (canvas.width - offsetXPx) / scale,
            (canvas.height - offsetYPx) / scale,
            toDevice,
        )
        canvas.restore()
    }
}

package dev.folio.app.spikes

import android.graphics.Canvas
import android.graphics.Color
import android.graphics.Matrix
import android.graphics.Paint
import androidx.annotation.WorkerThread
import androidx.ink.brush.Brush
import androidx.ink.brush.InputToolType
import androidx.ink.brush.StockBrushes
import androidx.ink.rendering.android.canvas.CanvasStrokeRenderer
import androidx.ink.strokes.MutableStrokeInputBatch
import androidx.ink.strokes.Stroke
import kotlin.math.ceil
import kotlin.math.max
import kotlin.math.min

/**
 * Committed content of the P01-S2 spike: an A4 college-ruled page with seeded ink strokes, drawn
 * for any page region. Stands in for `PageRenderer.draw` (05-canvas-rendering.md#page-renderer).
 */
internal class SpikePage private constructor(
    private val strokes: List<Stroke>,
    private val boundsPt: FloatArray, // left, top, right, bottom per stroke
) {
    val strokeCount: Int get() = strokes.size

    /**
     * Draws paper, template and the strokes intersecting the region onto [canvas], whose matrix
     * already maps page points to device pixels; [toDevice] is that matrix, for the stroke renderer.
     * HOT PATH (render thread): no allocation.
     */
    @WorkerThread
    @Suppress("LongParameterList") // region edges as plain floats avoid a RectF per tile
    fun draw(
        canvas: Canvas,
        painter: Painter,
        leftPt: Float,
        topPt: Float,
        rightPt: Float,
        bottomPt: Float,
        toDevice: Matrix,
    ) {
        val l = max(leftPt, 0f)
        val t = max(topPt, 0f)
        val r = min(rightPt, WIDTH_PT)
        val b = min(bottomPt, HEIGHT_PT)
        if (l >= r || t >= b) return
        canvas.save()
        canvas.clipRect(l, t, r, b)
        canvas.drawRect(l, t, r, b, painter.paper)
        val first = ceil((t - RULE_TOP_PT) / RULE_SPACING_PT).toInt().coerceAtLeast(0)
        var y = RULE_TOP_PT + first * RULE_SPACING_PT
        while (y <= b) {
            canvas.drawLine(l, y, r, y, painter.rule)
            y += RULE_SPACING_PT
        }
        if (MARGIN_X_PT in l..r) canvas.drawLine(MARGIN_X_PT, t, MARGIN_X_PT, b, painter.margin)
        for (i in strokes.indices) {
            val o = i * 4
            if (boundsPt[o] > r || boundsPt[o + 2] < l || boundsPt[o + 1] > b || boundsPt[o + 3] < t) continue
            painter.renderer.draw(canvas, strokes[i], toDevice)
        }
        canvas.restore()
    }

    /** Per-thread drawing state: the ink renderer caches per-stroke data and is not shared across threads. */
    class Painter {
        val renderer: CanvasStrokeRenderer = CanvasStrokeRenderer.create()
        val matrix = Matrix()
        val paper = Paint().apply { color = Color.WHITE }
        val rule =
            Paint(Paint.ANTI_ALIAS_FLAG).apply {
                color = RULE_ARGB.toInt()
                strokeWidth = RULE_WIDTH_PT
            }
        val margin =
            Paint(Paint.ANTI_ALIAS_FLAG).apply {
                color = MARGIN_ARGB.toInt()
                strokeWidth = RULE_WIDTH_PT
            }
    }

    companion object {
        const val WIDTH_PT = 595.28f
        const val HEIGHT_PT = 841.89f
        private const val MM_PT = 72f / 25.4f
        private const val RULE_SPACING_PT = 7.1f * MM_PT // college ruling (05-canvas-rendering.md#templates)
        private const val RULE_TOP_PT = 25f * MM_PT
        private const val MARGIN_X_PT = 25f * MM_PT
        private const val RULE_WIDTH_PT = 0.5f
        private const val RULE_ARGB = 0xFFC9D3E0
        private const val MARGIN_ARGB = 0xFFF2A6A6
        private const val BRUSH_EPSILON_PT = 0.05f
        private const val SAMPLE_INTERVAL_MS = 5L

        /** Builds ink strokes (meshes) for [synthetic]; takes a while for 1500 strokes. */
        @WorkerThread
        fun create(synthetic: List<SyntheticStroke>): SpikePage {
            val strokes = ArrayList<Stroke>(synthetic.size)
            val bounds = FloatArray(synthetic.size * 4)
            synthetic.forEachIndexed { i, s ->
                val stroke = s.toInk()
                val box = stroke.shape.computeBoundingBox()
                val o = i * 4
                if (box != null) {
                    bounds[o] = box.xMin
                    bounds[o + 1] = box.yMin
                    bounds[o + 2] = box.xMax
                    bounds[o + 3] = box.yMax
                }
                strokes += stroke
            }
            return SpikePage(strokes, bounds)
        }

        private fun SyntheticStroke.toInk(): Stroke {
            val family =
                when (brush) {
                    SyntheticBrush.PEN -> StockBrushes.pressurePen()
                    SyntheticBrush.MARKER -> StockBrushes.marker()
                    SyntheticBrush.HIGHLIGHTER -> StockBrushes.highlighter()
                }
            val inputs = MutableStrokeInputBatch()
            for (i in xsPt.indices) {
                inputs.add(
                    type = InputToolType.STYLUS,
                    x = xsPt[i],
                    y = ysPt[i],
                    elapsedTimeMillis = i * SAMPLE_INTERVAL_MS,
                    pressure = pressures[i],
                )
            }
            return Stroke(Brush.createWithColorIntArgb(family, argb, sizePt, BRUSH_EPSILON_PT), inputs)
        }
    }
}

package dev.folio.app.spikes

import kotlin.math.PI
import kotlin.math.cos
import kotlin.math.sin
import kotlin.random.Random

/** Brush family of a synthetic stroke (P01-S2). */
internal enum class SyntheticBrush { PEN, MARKER, HIGHLIGHTER }

/** One seeded stroke in page points; the view converts it to an androidx.ink Stroke. */
internal class SyntheticStroke(
    val brush: SyntheticBrush,
    val sizePt: Float,
    val argb: Int,
    val xsPt: FloatArray,
    val ysPt: FloatArray,
    val pressures: FloatArray,
)

/**
 * Handwriting-like strokes for the tile spike: short smoothed random walks along the lines of a
 * college-ruled page. Deterministic for a seed. Mix: 60% pen, 25% marker, 15% highlighter.
 */
internal object SyntheticStrokes {
    const val SEED = 20260927L
    const val COUNT = 1500

    fun generate(
        widthPt: Float,
        heightPt: Float,
        count: Int = COUNT,
        seed: Long = SEED,
    ): List<SyntheticStroke> {
        val random = Random(seed)
        return List(count) { stroke(random, widthPt, heightPt) }
    }

    private fun stroke(
        random: Random,
        widthPt: Float,
        heightPt: Float,
    ): SyntheticStroke {
        val roll = random.nextFloat()
        val brush =
            when {
                roll < PEN_SHARE -> SyntheticBrush.PEN
                roll < PEN_SHARE + MARKER_SHARE -> SyntheticBrush.MARKER
                else -> SyntheticBrush.HIGHLIGHTER
            }
        val sizePt =
            when (brush) {
                SyntheticBrush.PEN -> random.range(PEN_MIN_PT, PEN_MAX_PT)
                SyntheticBrush.MARKER -> random.range(MARKER_MIN_PT, MARKER_MAX_PT)
                SyntheticBrush.HIGHLIGHTER -> random.range(HIGHLIGHTER_MIN_PT, HIGHLIGHTER_MAX_PT)
            }
        val argb =
            when (brush) {
                SyntheticBrush.HIGHLIGHTER -> HIGHLIGHTER_COLORS[random.nextInt(HIGHLIGHTER_COLORS.size)]
                else -> INK_COLORS[random.nextInt(INK_COLORS.size)]
            }
        val n = random.nextInt(MIN_POINTS, MAX_POINTS + 1)
        val xs = FloatArray(n)
        val ys = FloatArray(n)
        val pressures = FloatArray(n)
        val margin = sizePt + EDGE_PT
        var x = random.range(margin, widthPt - margin)
        var y = random.range(margin, heightPt - margin)
        var heading = random.range(-HEADING_SPREAD, HEADING_SPREAD) // mostly left to right
        val stepPt = random.range(STEP_MIN_PT, STEP_MAX_PT)
        for (i in 0 until n) {
            xs[i] = x
            ys[i] = y
            pressures[i] = random.range(PRESSURE_MIN, 1f)
            heading += random.range(-TURN, TURN)
            x = (x + stepPt * cos(heading)).coerceIn(margin, widthPt - margin)
            y = (y + stepPt * sin(heading)).coerceIn(margin, heightPt - margin)
        }
        return SyntheticStroke(brush, sizePt, argb, xs, ys, pressures)
    }

    private fun Random.range(
        from: Float,
        until: Float,
    ): Float = from + nextFloat() * (until - from)

    private const val PEN_SHARE = 0.60f
    private const val MARKER_SHARE = 0.25f
    private const val PEN_MIN_PT = 0.5f
    private const val PEN_MAX_PT = 2f
    private const val MARKER_MIN_PT = 1.5f
    private const val MARKER_MAX_PT = 4f
    private const val HIGHLIGHTER_MIN_PT = 8f
    private const val HIGHLIGHTER_MAX_PT = 14f
    private const val MIN_POINTS = 20
    private const val MAX_POINTS = 80
    private const val STEP_MIN_PT = 1f
    private const val STEP_MAX_PT = 3f
    private const val EDGE_PT = 4f
    private const val PRESSURE_MIN = 0.3f
    private const val HEADING_SPREAD = 0.3f
    private const val TURN = (PI / 5).toFloat()
    private val INK_COLORS = intArrayOf(0xFF1A1A1A.toInt(), 0xFF1F4FB8.toInt(), 0xFFC62828.toInt(), 0xFF2E7D32.toInt())
    private val HIGHLIGHTER_COLORS = intArrayOf(0x66FFEB3B, 0x6681D4FA, 0x66F48FB1)
}

package dev.folio.app.spikes

import android.graphics.Bitmap
import kotlin.math.abs
import kotlin.math.max

/** Accumulates per-pixel differences between two ARGB images (P01-S2 visual equality check). */
internal class PixelDiff(
    private val threshold: Int = DEFAULT_THRESHOLD,
) {
    var pixels = 0L
        private set
    var differing = 0L
        private set
    private var channelSum = 0L

    /** Percentage of pixels whose largest channel difference exceeds the threshold. */
    val differingPct: Double get() = if (pixels == 0L) 0.0 else differing * PERCENT / pixels

    /** Mean absolute difference per color channel, 0..255. */
    val meanChannelDiff: Double get() = if (pixels == 0L) 0.0 else channelSum.toDouble() / (pixels * CHANNELS)

    /** Adds the first [count] pixels of [a] and [b]. */
    fun add(
        a: IntArray,
        b: IntArray,
        count: Int = a.size,
    ) {
        for (i in 0 until count) {
            val dr = abs((a[i] shr RED and BYTE) - (b[i] shr RED and BYTE))
            val dg = abs((a[i] shr GREEN and BYTE) - (b[i] shr GREEN and BYTE))
            val db = abs((a[i] and BYTE) - (b[i] and BYTE))
            channelSum += dr + dg + db
            if (max(dr, max(dg, db)) > threshold) differing++
        }
        pixels += count
    }

    /** Compares two same-sized bitmaps row by row. */
    fun addBitmaps(
        a: Bitmap,
        b: Bitmap,
    ): PixelDiff {
        require(a.width == b.width && a.height == b.height) { "bitmap sizes differ" }
        val rowA = IntArray(a.width)
        val rowB = IntArray(a.width)
        for (y in 0 until a.height) {
            a.getPixels(rowA, 0, a.width, 0, y, a.width, 1)
            b.getPixels(rowB, 0, b.width, 0, y, b.width, 1)
            add(rowA, rowB)
        }
        return this
    }

    private companion object {
        const val DEFAULT_THRESHOLD = 32
        const val RED = 16
        const val GREEN = 8
        const val BYTE = 0xFF
        const val CHANNELS = 3
        const val PERCENT = 100.0
    }
}

