        )
    }

    /** A Markdown table of [results]: baseline error in px per zoom, cap error, size, layout time. */
    fun table(results: List<BaselineProbeResult>): String =
        buildString {
            appendLine("| Font | Method | Lines | Max baseline error px z1 / z2 / z4 | Cap error px | Size pt | Cap ratio | Layout ms/para |")
            appendLine("|---|---|---|---|---|---|---|---|")
            for (r in results) {
