                appendLine(
                    "| ${r.family} | ${r.method} | ${r.lines} | $errors | ${"%.3f".format(r.capErrorPx)} | " +
                        "${"%.2f".format(r.fontSizePt)} | ${"%.3f".format(r.capRatio)} | ${"%.2f".format(r.layoutMedianMs)} |",
                )
            }
        }
}

