        spikeDir.mkdirs()
        fixturesDir.mkdirs()
        removedOnStart = SpikePacker.removeStaleTmp(spikeDir)
        observer =
            object : FileObserver(listOf(fixturesDir, spikeDir), OBSERVED) {
